1	import { describe, expect, it } from "vitest";
2	import {
3	  initial,
4	  reduce,
5	  nextFace,
6	  runFace,
7	  undoFace,
8	  metricFace,
9	  connectFace,
10	  attachedRun,
11	  idleDeadline,
12	  IDLE_OFF_MS,
13	  type DeckState,
14	  type Offer,
15	} from "./state";
16	
17	const held = (id: string, name = "Thursday") => ({ id, name, packTitle: "The Long Kiln" });
18	const offer: Offer = {
19	  seq: 42,
20	  primary: { id: "roll", label: "Roll the Weather", kind: "rollTable" },
21	  moves: [],
22	  undo: { what: "A dry wind." },
23	  needsPage: null,
24	  presets: [],
25	};
26	const T = 1_000_000;
27	
28	// Signed in and switched on: the two things that had to be true before a
